const I18nContext = createContext(null);

export function I18nProvider({ children }) {
  const [lang, setLang] = useState(() => {
    try {
      const saved = localStorage.getItem('lg-lang');
      return LANG_CODES.includes(saved) ? saved : 'en';
    } catch (e) { return 'en'; }
  });

  useEffect(() => {
    document.documentElement.lang = lang;
    document.documentElement.dir = 'ltr';
    try { localStorage.setItem('lg-lang', lang); } catch (e) {}
  }, [lang]);

  const t = (key, vars) => {
    let out = DICT[key] && DICT[key][lang] ? DICT[key][lang] : (typeof key === 'string' ? key : '');
    if (vars) {
      for (const [k, v] of Object.entries(vars)) {
        out = out.split(`{${k}}`).join(String(v ?? ''));
      }
    }
    return out;
  };

  return (
    <I18nContext.Provider value={{ lang, setLang, t, languages: LANGUAGES }}>
      {children}
    </I18nContext.Provider>
  );
}

export const useI18n = () => useContext(I18nContext);